func crystallineToBool(value js.Value) (bool, error) {
	var zero bool

	if value.Type() != js.TypeBoolean {
		return zero, errors.New("expected a boolean")
	}

	return bool(value.Bool()), nil
}

func crystallineToBytes(value js.Value) ([]byte, error) {
	if value.IsUndefined() || value.IsNull() {
		return nil, nil
	}

	if !value.InstanceOf(js.Global().Get("Uint8Array")) {
		return nil, errors.New("expected a Uint8Array")
	}

	out := make([]byte, value.Get("length").Int())
	if copied := js.CopyBytesToGo(out, value); copied != len(out) {
		return nil, errors.New("expected a Uint8Array")
	}

	return out, nil
}

